using System.Text;using System.Text.Json;namespace QuantForge.Core;public sealed class AndroidStrategyDraftCardFileStore{private readonly string _path;public AndroidStrategyDraftCardFileStore(string path){if(string.IsNullOrWhiteSpace(path))throw new ArgumentException("A card path is required.",nameof(path));_path=Path.GetFullPath(path);}public void Save(AndroidStrategyDraftCard value){ArgumentNullException.ThrowIfNull(value);if(value.CanSubmitOrders)throw new InvalidOperationException("Android strategy draft cards cannot grant order authority.");Directory.CreateDirectory(Path.GetDirectoryName(_path)!);File.WriteAllText(_path,JsonSerializer.Serialize(value,new JsonSerializerOptions{WriteIndented=true}),new UTF8Encoding(false));}public AndroidStrategyDraftCard Load(){var value=JsonSerializer.Deserialize<AndroidStrategyDraftCard>(File.ReadAllText(_path))??throw new InvalidOperationException("Android strategy draft card JSON is invalid.");if(value.CanSubmitOrders)throw new InvalidOperationException("Persisted Android strategy draft card grants order authority.");return value;}}
